def generate_baseline_with_parser_fix(
    trip_duration,
    interests,
    budget_level,
    seed
):
    """
    Reuse the original baseline generator and
    JSON-safe tools, with minimal response-text
    normalization before original M4 parsing.
    """

    original_safe_call = call_gemini_with_safe_tools

    def normalized_safe_call(prompt, seed, max_attempts=3):

        response = original_safe_call(
            prompt=prompt,
            seed=seed,
            max_attempts=max_attempts
        )

        text = getattr(response, "text", None)

        if not isinstance(text, str):
            return response

        raw_text = text.strip()

        if raw_text.startswith("json\n"):
            candidate = raw_text[len("json\n"):].lstrip()

            if candidate.startswith("{"):
                # Return an object preserving tool history
                return SimpleNamespace(
                    text=candidate,
                    automatic_function_calling_history=(
                        response.automatic_function_calling_history
                    )
                )

        return response

    with patch.dict(
        original_generate_baseline_with_safe_tools.__globals__,
        {
            "call_gemini_with_safe_tools":
                normalized_safe_call
        }
    ):
        return original_generate_baseline_with_safe_tools(
            trip_duration=trip_duration,
            interests=interests,
            budget_level=budget_level,
            seed=seed
        )

