def score_activity_preference(itinerary, trip_duration, interests):
    required = 2 * trip_duration

    if not isinstance(itinerary, dict):
        return 0.0

    days = itinerary.get("days", [])

    if not isinstance(days, list):
        return 0.0

    activity_lookup = activities.set_index("place_id")["interest_group"]

    matching_count = 0
    seen_ids = set()

    # Only evaluate the requested number of days
    for day in days[:trip_duration]:
        if not isinstance(day, dict):
            continue

        day_activities = day.get("activities", [])

        if not isinstance(day_activities, list):
            continue

        # Only the first two activity slots per day count
        for pid in day_activities[:2]:
            if not isinstance(pid, str):
                continue

            if pid in seen_ids:
                continue

            seen_ids.add(pid)

            if pid not in activity_lookup.index:
                continue

            if activity_lookup.loc[pid] in interests:
                matching_count += 1

    score = 100 * matching_count / required

    return round(score, 2)

