def score_restaurant_budget(itinerary, trip_duration, budget_level):
    required = 2 * trip_duration

    if not isinstance(itinerary, dict):
        return 0.0

    days = itinerary.get("days", [])

    if not isinstance(days, list):
        return 0.0

    restaurant_lookup = restaurants.set_index("place_id")["budget_level"]

    matching_count = 0

    # Evaluate only the requested number of days
    for day in days[:trip_duration]:
        if not isinstance(day, dict):
            continue

        day_restaurants = day.get("restaurants", [])

        if not isinstance(day_restaurants, list):
            continue

        # Only the first two restaurant slots per day count
        for pid in day_restaurants[:2]:
            if not isinstance(pid, str):
                continue

            if pid not in restaurant_lookup.index:
                continue

            if restaurant_lookup.loc[pid] == budget_level:
                matching_count += 1

    score = 100 * matching_count / required

    return round(score, 2)

