def score_hotel_budget(itinerary, budget_level):
    if not isinstance(itinerary, dict):
        return 0.0

    hotel_id = itinerary.get("hotel_id")

    if not isinstance(hotel_id, str):
        return 0.0

    hotel_lookup = hotels.set_index("place_id")["budget_level"]

    if hotel_id not in hotel_lookup.index:
        return 0.0

    if hotel_lookup.loc[hotel_id] == budget_level:
        return 100.0

    return 0.0

