def score_itinerary_feasibility(itinerary, trip_duration):
    try:
        is_valid, errors = validate_itinerary(
            itinerary=itinerary,
            trip_duration=trip_duration
        )

        return {
            "ifr_score": 100.0 if is_valid else 0.0,
            "feasible": bool(is_valid),
            "validation_errors": errors
        }

    except Exception as e:
        return {
            "ifr_score": 0.0,
            "feasible": False,
            "validation_errors": [
                f"Validation exception: {type(e).__name__}: {e}"
            ]
        }

