def calculate_tool_coverage(tool_calls):
    if not isinstance(tool_calls, list):
        return 0.0

    called_tools = {
        name for name in tool_calls
        if isinstance(name, str)
    }

    matched_tools = called_tools & REQUIRED_TOOLS

    return round(
        len(matched_tools) / len(REQUIRED_TOOLS) * 100,
        2
    )

